function Search() {
  const { books, loading, error } = useBooks();
  const [query, setQuery] = useState('');
  const filtered = books.filter(b => b.title.toLowerCase().includes(query.toLowerCase()));

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Something went wrong: {error.message}</p>;

  return (
    <div>
      <input type="search" aria-label="Search books" value={query} onChange={e => setQuery(e.target.value)} />
      {filtered.length === 0 && <p>No books match "{query}"</p>}
      <ul>
        {filtered.map(b => <li key={b.id}>{b.title}</li>)}
      </ul>
    </div>
  );
}
